const headers = ($json && $json.headers) ? $json.headers : {};
const body = ($json && $json.body) ? $json.body : ($json ?? {});
const env = $env || {};

function getHeader(name) {
  const lower = String(name || '').toLowerCase();
  if (headers[lower] !== undefined) return headers[lower];
  if (headers[name] !== undefined) return headers[name];
  const key = Object.keys(headers).find((k) => k.toLowerCase() === lower);
  return key ? headers[key] : undefined;
}

function isTruthy(value) {
  if (value === undefined || value === null) return false;
  const v = String(value).trim().toLowerCase();
  return ['1', 'true', 'yes', 'y', 'on', 'enabled'].includes(v);
}

function error(status, message, extra = {}) {
  return [{
    json: {
      ok: false,
      status_code: status,
      error: message,
      ...extra,
    }
  }];
}

function pickFirst(paths, fallback = null) {
  for (const path of paths) {
    const parts = String(path).split('.').filter(Boolean);
    let cur = body;
    for (const part of parts) {
      if (cur === null || cur === undefined) {
        cur = undefined;
        break;
      }
      cur = cur?.[part];
    }
    if (cur !== undefined && cur !== null && String(cur).trim() !== '') return cur;
  }
  return fallback;
}

function parseJsonMap(text) {
  const raw = String(text || '').trim();
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
  } catch (error) {}
  return null;
}

function parseYamlMap(text) {
  const map = {};
  const lines = String(text || '').split(/\r?\n/);
  for (const line of lines) {
    const trimmed = String(line || '').trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const idx = trimmed.indexOf(':');
    if (idx <= 0) continue;
    const key = trimmed.slice(0, idx).trim();
    let value = trimmed.slice(idx + 1).trim();
    if (!key) continue;
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    map[key] = value;
  }
  return map;
}

function loadRealmMap(jsonText, yamlText) {
  const jsonMap = parseJsonMap(jsonText);
  if (jsonMap && Object.keys(jsonMap).length) return jsonMap;
  return parseYamlMap(yamlText);
}

function pickRealmValue(map, realmKey) {
  if (!map || typeof map !== 'object') return '';
  const realmStr = String(realmKey || '').trim();
  const candidates = [realmStr, realmStr.toLowerCase(), 'default', '*'];
  for (const key of candidates) {
    if (!key) continue;
    const value = map[key];
    if (value === undefined || value === null) continue;
    const trimmed = String(value).trim();
    if (trimmed) return trimmed;
  }
  return '';
}

function deriveRealmFromProjectPath(path) {
  const p = String(path || '').trim();
  if (!p) return '';
  const first = p.split('/')[0] || '';
  return first.trim();
}

function looksLikeYamlMap(text) {
  const t = String(text || '').trim();
  if (!t) return false;
  if (/^https?:\/\//i.test(t)) return false;
  if (t.includes(String.fromCharCode(10)) || t.includes(String.fromCharCode(13)) || t.includes('\\n')) return true;
  if (/^\s*(default|\*)\s*:\s*\S+/i.test(t)) return true;
  return false;
}

function resolveGitlabWebhookSecretsMap() {
  const json = String(env.GITLAB_WEBHOOK_SECRETS_JSON || '').trim();
  const yaml = String(env.GITLAB_WEBHOOK_SECRETS_YAML || '').trim();
  if (json || yaml) return loadRealmMap(json, yaml);
  const raw = String(env.GITLAB_WEBHOOK_SECRET || '').trim();
  if (looksLikeYamlMap(raw)) return loadRealmMap('', raw);
  return {};
}

const eventHeader = String(getHeader('x-gitlab-event') || body.event_type || body.object_kind || '').trim();
const event = eventHeader.toLowerCase();
if (!event.includes('issue')) {
  return [{ json: { ok: true, status_code: 200, skipped: true, reason: 'not_issue_event', event: eventHeader } }];
}

const token = String(getHeader('x-gitlab-token') || '').trim();
const scalarSecret = String(env.GITLAB_WEBHOOK_SECRET || '').trim();
const secretMap = resolveGitlabWebhookSecretsMap();

const projectPath = pickFirst(['project.path_with_namespace', 'project.path', 'project.path_with_namespace', 'project_path'], '') || '';
const realmFromProject = deriveRealmFromProjectPath(projectPath);

let matchedSecretKey = '';
let expectedSecret = '';
if (secretMap && Object.keys(secretMap).length) {
  const candidates = [realmFromProject, (realmFromProject || '').toLowerCase(), 'default', '*'].filter(Boolean);
  for (const k of candidates) {
    const v = secretMap[k];
    if (v !== undefined && v !== null && String(v).trim()) {
      matchedSecretKey = k;
      expectedSecret = String(v).trim();
      break;
    }
  }
}

const hasAnySecret = Boolean(scalarSecret) || Boolean(expectedSecret);
if (!hasAnySecret) {
  return error(424, 'missing webhook secret', { missing: ['GITLAB_WEBHOOK_SECRET'] });
}

const mustMatch = expectedSecret || scalarSecret;
if (mustMatch && token !== mustMatch) {
  return error(401, 'invalid token', { event: eventHeader });
}

const realm = realmFromProject
  || (matchedSecretKey && matchedSecretKey !== 'default' ? String(matchedSecretKey).trim() : '')
  || String(env.N8N_REALM || env.N8N_OBSERVER_REALM || env.ZULIP_REALM || 'default').trim()
  || 'default';

const dryRun = isTruthy(pickFirst(['dry_run'], false)) || isTruthy(env.ITSM_CIR_NOTIFY_DRY_RUN) || isTruthy(env.GITLAB_CIR_NOTIFY_DRY_RUN);

const issueId = pickFirst(['object_attributes.id', 'issue.id'], null);
const issueIid = pickFirst(['object_attributes.iid', 'issue.iid'], null);
const issueTitle = String(pickFirst(['object_attributes.title', 'issue.title'], '') || '').trim();
const issueUrl = String(pickFirst(['object_attributes.url', 'issue.url'], '') || '').trim();
const issueDescription = String(pickFirst(['object_attributes.description', 'issue.description'], '') || '').trim();

const updatedAt = String(pickFirst(['object_attributes.updated_at', 'object_attributes.last_edited_at', 'issue.updated_at'], '') || '').trim();

function labelTitles(raw) {
  const labels = Array.isArray(raw) ? raw : [];
  const out = [];
  for (const l of labels) {
    if (l === null || l === undefined) continue;
    if (typeof l === 'string') {
      const t = l.trim();
      if (t) out.push(t);
      continue;
    }
    if (typeof l === 'object') {
      const t = String(l.title ?? l.name ?? '').trim();
      if (t) out.push(t);
    }
  }
  return out;
}

const changesLabels = (body && typeof body === 'object' && body.changes && typeof body.changes === 'object')
  ? body.changes.labels
  : null;

const changesPrevRaw = (changesLabels && typeof changesLabels === 'object')
  ? (Array.isArray(changesLabels.previous) ? changesLabels.previous : (Array.isArray(changesLabels.before) ? changesLabels.before : null))
  : null;
const changesCurRaw = (changesLabels && typeof changesLabels === 'object')
  ? (Array.isArray(changesLabels.current) ? changesLabels.current : (Array.isArray(changesLabels.after) ? changesLabels.after : null))
  : null;

const hasLabelsChange = Boolean(changesPrevRaw || changesCurRaw);
if (!hasLabelsChange) {
  return [{ json: { ok: true, status_code: 200, skipped: true, reason: 'no_label_change_payload', realm, project_path: projectPath, issue_iid: issueIid, issue_url: issueUrl } }];
}

const prevLabels = labelTitles(changesPrevRaw || []);
const curLabels = labelTitles(changesCurRaw || pickFirst(['object_attributes.labels', 'labels'], []));

const curSet = new Set(curLabels);
const prevSet = new Set(prevLabels);
const added = curLabels.filter((t) => !prevSet.has(t));

const cirLabel = String(env.ITSM_CIR_LABEL || 'ITSM/継続的改善').trim() || 'ITSM/継続的改善';
if (!curSet.has(cirLabel)) {
  return [{ json: { ok: true, status_code: 200, skipped: true, reason: 'not_cir_issue', realm, project_path: projectPath, issue_iid: issueIid, issue_url: issueUrl } }];
}

const approvedLabel = String(env.ITSM_CIR_APPROVED_LABEL || '状態/Approved').trim() || '状態/Approved';
const closedLabel = String(env.ITSM_CIR_CLOSED_LABEL || '状態/Closed').trim() || '状態/Closed';

let notifyKind = '';
let statusLabel = '';
if (added.includes(closedLabel)) {
  notifyKind = 'closed';
  statusLabel = closedLabel;
} else if (added.includes(approvedLabel)) {
  notifyKind = 'approved';
  statusLabel = approvedLabel;
}

if (!notifyKind) {
  return [{ json: { ok: true, status_code: 200, skipped: true, reason: 'no_target_status_label_added', realm, project_path: projectPath, issue_iid: issueIid, issue_url: issueUrl, added_labels: added } }];
}

function extractRequesterEmails(text) {
  const raw = String(text || '');

  const candidates = [];
  const rowPatterns = [
    /\|\s*起票者\s*\|\s*([^|\n]+)\|/i,
    /\|\s*Submitted\s*by\s*\|\s*([^|\n]+)\|/i,
    /requester[_\s-]*email\s*[:：]\s*([^\s\n]+)/i,
  ];
  for (const re of rowPatterns) {
    const m = raw.match(re);
    if (m && m[1]) candidates.push(String(m[1]));
  }

  // Fallback: allow any email in the description.
  if (candidates.length === 0) candidates.push(raw);

  const joined = candidates.join(' ');
  const emails = [];
  const re = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig;
  let mm;
  while ((mm = re.exec(joined)) !== null) {
    const e = String(mm[0] || '').trim();
    if (e) emails.push(e);
  }

  // De-dupe
  const seen = new Set();
  const out = [];
  for (const e of emails) {
    const k = e.toLowerCase();
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(e);
  }
  return out;
}

const recipients = extractRequesterEmails(issueDescription);
if (recipients.length === 0) {
  return [{
    json: {
      ok: true,
      status_code: 200,
      skipped: true,
      reason: 'missing_requester_email',
      realm,
      project_path: projectPath,
      issue_iid: issueIid,
      issue_url: issueUrl,
      status_label: statusLabel,
      hint: 'Issue description の「起票者」に Zulip メールアドレスを入れてください。'
    }
  }];
}

const prefixApproved = String(env.ITSM_CIR_NOTIFY_APPROVED_PREFIX || '以前のご要望').trim() || '以前のご要望';
const prefixClosed = String(env.ITSM_CIR_NOTIFY_CLOSED_PREFIX || '以前のご要望').trim() || '以前のご要望';

let notifyText = '';
if (notifyKind === 'approved') {
  notifyText = `${prefixApproved}「${issueTitle || '（件名なし）'}」は承認されましたので、これから改善します。`;
} else {
  notifyText = `${prefixClosed}「${issueTitle || '（件名なし）'}」は対応が完了したため、クローズしました。`;
}

const lines = [
  notifyText,
  issueUrl ? `CIR: ${issueUrl}` : null,
  '',
  `Status: ${statusLabel}`,
  `Realm: ${realm}`,
].filter((v) => v !== null);
const content = lines.join('\n');

const eventKey = `itsm:cir_notify:${projectPath || 'unknown'}#${issueIid || issueId || 'unknown'}:${statusLabel}:${updatedAt || 'no-ts'}`;
const correlationId = `gitlab:${projectPath || 'unknown'}#${issueIid || ''}`;

const sorAudit = {
  record_type: 'sor_audit_event',
  realm,
  occurred_at: updatedAt || null,
  action: 'cir.requester_notified',
  source: 'gitlab',
  actor_type: 'human',
  actor: { name: String(pickFirst(['user.username', 'user.name', 'user_username', 'user_name'], 'unknown')) },
  resource_type: 'gitlab_issue',
  correlation_id: correlationId,
  reply_target: {
    source: 'gitlab',
    project_path: projectPath || null,
    issue_iid: issueIid || null,
    url: issueUrl || null,
  },
  summary: notifyKind === 'approved' ? `CIR 承認通知: ${issueTitle}` : `CIR クローズ通知: ${issueTitle}`,
  message: content,
  after: {
    notify_kind: notifyKind,
    status_label: statusLabel,
    recipients,
    gitlab_project_path: projectPath || null,
    gitlab_issue_url: issueUrl || null,
  },
  integrity: { event_key: eventKey }
};

if (dryRun) {
  return [{
    json: {
      ok: true,
      status_code: 200,
      dry_run: true,
      realm,
      notify_candidate_flag: '',
      would_notify: true,
      notify_kind: notifyKind,
      status_label: statusLabel,
      recipients,
      content,
      ...sorAudit,
    }
  }];
}

return [{
  json: {
    ok: true,
    status_code: 200,
    realm,
    notify_candidate_flag: 'true',
    notify_kind: notifyKind,
    status_label: statusLabel,
    recipients,
    content,
    ...sorAudit,
  }
}];

const base = $json ?? {};

function isTruthy(value) {
  if (value === undefined || value === null) return false;
  const v = String(value).trim().toLowerCase();
  return ['1', 'true', 'yes', 'y', 'on', 'enabled'].includes(v);
}

const dryRun = Boolean(base.dry_run) || isTruthy($env.ITSM_CIR_NOTIFY_DRY_RUN) || isTruthy($env.GITLAB_CIR_NOTIFY_DRY_RUN);
if (dryRun) {
  return [{ json: { ...base, zulip_notify: { ok: true, skipped: true, reason: 'dry_run' } } }];
}

const realm = String(base.realm || $env.N8N_REALM || $env.N8N_OBSERVER_REALM || 'default').trim() || 'default';
const recipients = Array.isArray(base.recipients) ? base.recipients : [];
const content = String(base.content || '').trim();

if (!content) {
  return [{ json: { ...base, zulip_notify: { ok: false, skipped: true, reason: 'empty_content' } } }];
}
if (recipients.length === 0) {
  return [{ json: { ...base, zulip_notify: { ok: false, skipped: true, reason: 'missing_recipients' } } }];
}

function parseJsonMap(text) {
  const raw = String(text || '').trim();
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
  } catch (error) {}
  return null;
}

function parseYamlMap(text) {
  const map = {};
  const lines = String(text || '').split(/\r?\n/);
  for (const line of lines) {
    const trimmed = String(line || '').trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const idx = trimmed.indexOf(':');
    if (idx <= 0) continue;
    const key = trimmed.slice(0, idx).trim();
    let value = trimmed.slice(idx + 1).trim();
    if (!key) continue;
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    map[key] = value;
  }
  return map;
}

function loadRealmMap(jsonText, yamlText) {
  const jsonMap = parseJsonMap(jsonText);
  if (jsonMap && Object.keys(jsonMap).length) return jsonMap;
  return parseYamlMap(yamlText);
}

function pickRealmValue(map, realmKey) {
  if (!map || typeof map !== 'object') return '';
  const realmStr = String(realmKey || '').trim();
  const candidates = [realmStr, realmStr.toLowerCase(), 'default', '*'];
  for (const key of candidates) {
    if (!key) continue;
    const value = map[key];
    if (value === undefined || value === null) continue;
    const trimmed = String(value).trim();
    if (trimmed) return trimmed;
  }
  return '';
}

function resolveZulipCredentials(realmKey) {
  const rk = String(realmKey || '').trim() || 'default';

  const baseFromMap = pickRealmValue(
    loadRealmMap($env.N8N_ZULIP_API_BASE_URL || '', $env.N8N_ZULIP_API_BASE_URL || ''),
    rk
  );
  const emailFromMap = pickRealmValue(
    loadRealmMap($env.N8N_ZULIP_BOT_EMAIL || '', $env.N8N_ZULIP_BOT_EMAIL || ''),
    rk
  );
  const keyFromMap = pickRealmValue(
    loadRealmMap($env.N8N_ZULIP_BOT_TOKEN || '', ($env.N8N_ZULIP_BOT_TOKEN || $env.ZULIP_BOT_TOKEN || '')),
    rk
  );

  const fallbackBase = String($env.ZULIP_BASE_URL || $env.N8N_ZULIP_API_BASE_URL || '').trim();
  const fallbackEmail = String($env.ZULIP_BOT_EMAIL || $env.N8N_ZULIP_BOT_EMAIL || '').trim();
  const fallbackKey = String($env.ZULIP_BOT_API_KEY || $env.N8N_ZULIP_BOT_TOKEN || $env.ZULIP_BOT_TOKEN || '').trim();

  let baseUrl = baseFromMap || fallbackBase;
  baseUrl = baseUrl.replace(/\/+$/, '');
  if (baseUrl.endsWith('/api/v1')) baseUrl = baseUrl.slice(0, -'/api/v1'.length);
  baseUrl = baseUrl.replace(/\/+$/, '');

  const email = emailFromMap || fallbackEmail;
  const apiKey = keyFromMap || fallbackKey;

  return { base_url: baseUrl, email, api_key: apiKey };
}

const zulip = resolveZulipCredentials(realm);
if (!zulip.base_url || !zulip.email || !zulip.api_key) {
  return [{
    json: {
      ...base,
      zulip_notify: {
        ok: false,
        skipped: true,
        reason: 'missing_zulip_credentials',
        realm,
        has_base_url: Boolean(zulip.base_url),
        has_email: Boolean(zulip.email),
        has_api_key: Boolean(zulip.api_key)
      }
    }
  }];
}

const apiBase = zulip.base_url.endsWith('/api/v1') ? zulip.base_url : `${zulip.base_url}/api/v1`;
const auth = Buffer.from(`${zulip.email}:${zulip.api_key}`).toString('base64');

const formBody = Object.entries({
  type: 'private',
  to: JSON.stringify(recipients),
  content,
})
  .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
  .join('&');

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${apiBase}/messages`,
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      Authorization: `Basic ${auth}`,
    },
    body: formBody,
    json: true,
    timeout: 8000,
  });

  return [{
    json: {
      ...base,
      zulip_notify: {
        ok: true,
        status_code: 200,
        type: 'private',
        recipients: recipients,
        sent_at: new Date().toISOString()
      }
    }
  }];
} catch (err) {
  const status = err?.response?.statusCode || err?.statusCode || err?.httpCode || null;
  const responseBody = err?.response?.body || err?.response?.data || null;
  return [{
    json: {
      ...base,
      zulip_notify: {
        ok: false,
        status_code: status || 500,
        error: String(err?.message || err),
        response_body: responseBody,
      }
    }
  }];
}
